"use client";

import { useImperativeHandle, useLayoutEffect, useRef, type ComponentProps } from "react";
import "./slider.css";

export type SliderProps = Omit<ComponentProps<"input">, "type">;

/**
 * A native range input with an ink fill that tracks the value and a raised
 * thumb that grows slightly while dragged. Pair it with a number field when
 * people need exact entry.
 */
export function Slider({ ref, onInput, ...props }: SliderProps) {
  const input = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => input.current!, []);

  function sync() {
    const element = input.current;
    if (!element) return;
    const min = Number(element.min || 0);
    const max = Number(element.max || 100);
    const ratio = max > min ? (Number(element.value) - min) / (max - min) : 0;
    element.style.setProperty("--fill", `${Math.min(1, Math.max(0, ratio)) * 100}%`);
  }

  // Controlled values change without an input event; resync every render.
  useLayoutEffect(sync);

  return (
    <input
      data-slot="slider"
      {...props}
      ref={input}
      type="range"
      onInput={(event) => {
        sync();
        onInput?.(event);
      }}
    />
  );
}

/* slider.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="slider"] {
    display: block;
    width: 100%;
    min-width: 0;
    height: var(--control-height);
    margin: 0;
    appearance: none;
    background: transparent;
    border-radius: var(--radius-control);
    outline: none;
    cursor: pointer;
    touch-action: manipulation;
  }

  [data-slot="slider"]:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }

  [data-slot="slider"]::-webkit-slider-runnable-track {
    height: 4px;
    border-radius: 2px;
    background: linear-gradient(
      to right,
      var(--accent) 0 var(--fill, 50%),
      color-mix(in srgb, var(--border-strong) 45%, var(--sunken)) var(--fill, 50%) 100%
    );
    box-shadow: inset 0 1px 1px rgb(20 20 28 / 12%);
  }
  [data-slot="slider"]::-moz-range-track {
    height: 4px;
    border-radius: 2px;
    background: color-mix(in srgb, var(--border-strong) 45%, var(--sunken));
  }
  [data-slot="slider"]::-moz-range-progress {
    height: 4px;
    border-radius: 2px;
    background: var(--accent);
  }
  [data-slot="slider"]::-webkit-slider-thumb {
    box-sizing: border-box;
    width: 20px;
    height: 20px;
    margin-top: -8px;
    appearance: none;
    border: 0;
    border-radius: 50%;
    background: var(--raised);
    box-shadow: var(--shadow-raised);
    transition: transform 200ms var(--ease-settle);
  }
  [data-slot="slider"]::-moz-range-thumb {
    box-sizing: border-box;
    width: 20px;
    height: 20px;
    border: 0;
    border-radius: 50%;
    background: var(--raised);
    box-shadow: var(--shadow-raised);
    transition: transform 200ms var(--ease-settle);
  }
  [data-theme="dark"] [data-slot="slider"]::-webkit-slider-thumb,
  :root[data-theme="dark"] [data-slot="slider"]::-webkit-slider-thumb {
    background: var(--foreground);
  }
  [data-theme="dark"] [data-slot="slider"]::-moz-range-thumb {
    background: var(--foreground);
  }
  [data-slot="slider"]:active:not(:disabled)::-webkit-slider-thumb {
    transform: scale(1.12);
  }
  [data-slot="slider"]:active:not(:disabled)::-moz-range-thumb {
    transform: scale(1.12);
  }
  [data-slot="slider"]:focus-visible {
    outline: none;
  }
  [data-slot="slider"]:focus-visible::-webkit-slider-thumb {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  [data-slot="slider"]:focus-visible::-moz-range-thumb {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  @media (forced-colors: active) {
    [data-slot="slider"]:focus-visible {
      outline-color: Highlight;
    }
    [data-slot="slider"] {
      forced-color-adjust: none;
    }
    [data-slot="slider"]::-webkit-slider-runnable-track {
      background: CanvasText;
    }
    [data-slot="slider"]::-moz-range-track {
      background: CanvasText;
    }
    [data-slot="slider"]::-webkit-slider-thumb {
      background: CanvasText;
      border-color: Canvas;
    }
    [data-slot="slider"]::-moz-range-thumb {
      background: CanvasText;
      border-color: Canvas;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="slider"]::-webkit-slider-thumb {
      transition: none;
    }
    [data-slot="slider"]:active::-webkit-slider-thumb {
      transform: none;
    }
  }
}
